import assert from 'node:assert/strict';
import {resolvePlayerContacts} from './player-contact.mjs';
const field={x:0,y:0,w:200,h:100};
const separate=(a,b)=>Math.hypot((b.x-a.x)/11,(b.y-a.y)/7);
let players=[{x:50,y:50,vx:2,vy:1},{x:56,y:50,vx:-2,vy:1}];
resolvePlayerContacts(players,field);
assert.ok(separate(...players)>=1-1e-9,'overlapping players separate');
assert.ok(players[0].vx<=players[1].vx,'players no longer move into each other');
assert.equal(players[0].vy,1,'tangential velocity is preserved');
players=[{x:15,y:30,vx:0,vy:0},{x:15,y:30,vx:0,vy:0}];
resolvePlayerContacts(players,field);
assert.ok(separate(...players)>=1-1e-9,'wall does not trap coincident players');
assert.ok(players.every(p=>p.x>=15&&p.x<=185&&p.y>=15&&p.y<=85));
players=[{x:30,y:40,vx:1,vy:0},{x:80,y:40,vx:-1,vy:0}];
const before=JSON.stringify(players);resolvePlayerContacts(players,field);assert.equal(JSON.stringify(players),before,'distant players remain unchanged');
players=[{x:50,y:50,vx:-1,vy:0},{x:57,y:50,vx:1,vy:0}];
resolvePlayerContacts(players,field);assert.equal(players[0].vx,-1);assert.equal(players[1].vx,1);
assert.throws(()=>resolvePlayerContacts([{x:NaN,y:1}],field),RangeError);
console.log('OK: contato, limites, afastamento e velocidade tangencial');
